import React, { useEffect, useState } from "react";
import axios from "axios";
import { API_URL } from "../config";

function BallotReceiptPage({ auth }) {
  const [votes, setVotes] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchVotes = async () => {
      try {
        const token = auth?.token || localStorage.getItem("token");

        if (!token) {
          setLoading(false);
          return;
        }

        const res = await axios.get(`${API_URL}/api/votes`, {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        });

        setVotes(Array.isArray(res.data) ? res.data : []);

      } catch (err) {
        console.error(err);
        alert("Failed to load ballot");
      } finally {
        setLoading(false);
      }
    };

    fetchVotes();
  }, [auth]);

  const groupedVotes = votes.reduce((acc, vote) => {
    if (!acc[vote.position]) acc[vote.position] = [];
    acc[vote.position].push(vote);
    return acc;
  }, {});

  const handlePrint = () => window.print();

  if (loading) return <p>Loading...</p>;

  return (
    <div style={{ maxWidth: 800, margin: "40px auto" }}>
      <div style={{
        background: "#fff",
        padding: 30,
        borderRadius: 12,
        textAlign: "center"
      }}>

        <h2>Official Voting Receipt</h2>
        <p>{new Date().toLocaleString()}</p>
        <span style={{
          background: "green",
          color: "#fff",
          padding: "4px 10px",
          borderRadius: 6
        }}>
          ✔ Verified Vote
        </span>

        {Object.keys(groupedVotes).length === 0 ? (
          <p>No vote records found.</p>
        ) : (
          Object.keys(groupedVotes).map((position) => (
            <div key={position} style={{ marginTop: 20, textAlign: "left" }}>
              <h3>{position}</h3>

              {groupedVotes[position].map((v, i) => (
                <div key={i} style={{
                  display: "flex",
                  gap: 10,
                  padding: 10,
                  borderBottom: "1px solid #eee"
                }}>
                  {v.image && (
                    <img
                      src={`${API_URL}/uploads/${v.image}`}
                      alt=""
                      width={50}
                    />
                  )}

                  <strong>{v.candidateName}</strong>
                </div>
              ))}
            </div>
          ))
        )}

        <button onClick={handlePrint} style={{
          marginTop: 20,
          padding: "10px 20px",
          background: "red",
          color: "#fff",
          border: "none"
        }}>
          Print Receipt
        </button>
      </div>
    </div>
  );
}

export default BallotReceiptPage;
